contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address newOwner) public payable {
        require(true);

        // read owner before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // attempt the state-changing call and record whether it reverted and its return value if any
        bool didRevert;
        bool retFalse = false;
        bool retval = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
            retFalse = (retval == false);
        }

        // read owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // Assert the general rule: non-reverting call must return true and set owner to newOwner;
        // reverting call must leave owner unchanged.
        assert((!didRevert && !retFalse && ownerAfter == newOwner) || (didRevert && ownerAfter == ownerBefore));
    }

    receive() external payable { }
}

